#include <iostream>
#include <cmath>
#include <algorithm>

int main() {
    long long number;
    std::cin >> number;
    int length = (int)(std::log10(std::abs(number)) + 1);

    auto generateOnes = [](long long n) -> long long {
        return ((long long)std::pow(10, n) - 1) / 9;
    };

    std::function<long long(long long, int)> compute = [&](long long n, int length) -> long long {
        long long ones = generateOnes(length);
        long long total = (n / ones) * length;
        n %= ones;
        if (n == 0) return total;
        long long option1 = (length + 1) + compute(ones - n, length - 1);
        long long option2 = compute(n, length - 1);
        return total + std::min(option1, option2);
    };

    std::cout << "" << compute(number, length) << std::endl;
    return 0;
}
